const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const quebec = ee.Geometry.Rectangle([-79.8, 45.0, -57.1, 63.0]); // Quebec bounding box
  const startDate = '2023-01-01';
  const endDate = '2023-12-31';

  // 2. Data Acquisition - MODIS Burned Area product
  const burnedArea = ee.ImageCollection('MODIS/061/MCD64A1')
    .filterDate(startDate, endDate)
    .filterBounds(quebec);

  const collectionSize = burnedArea.size().getInfo();
  console.log(`2023 Burned Area Images: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Create binary burned mask (BurnDate > 0 means burned)
  const burnedMask = burnedArea.select('BurnDate').max().gt(0);

  // 3. Processing - Calculate burned area in hectares
  // Each pixel is 500x500m = 25 hectares
  const pixelAreaHa = 25; // hectares per pixel

  // Count burned pixels
  const burnedStats = burnedMask.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: quebec,
    scale: 500,
    maxPixels: 1e9
  });

  const burnedPixels = burnedStats.get('BurnDate').getInfo();
  console.log(`Burned Pixels: ${burnedPixels}`);

  if (burnedPixels === null || burnedPixels === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Calculate total burned area in hectares
  const totalBurnedHa = burnedPixels * pixelAreaHa;
  console.log(`Total Burned Area: ${totalBurnedHa.toLocaleString()} hectares`);

  // 4. Validation & Final Answer
  if (totalBurnedHa === null || totalBurnedHa === undefined || isNaN(totalBurnedHa) || totalBurnedHa < 0) {
    console.log("<answer>C3</answer>");
  } else if (totalBurnedHa > 800000) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
